#include <stdio.h>
#include <assert.h>
#include <stdbool.h>

/* Minimal faithful model of target arch primitives for the predicate logic.
 * pte bit0 = writable, bit1 = dirty (matching pte_write()/pte_dirty()). */
typedef unsigned long pte_t;
#define FOLL_WRITE   0x01
#define FOLL_FORCE   0x10
#define FOLL_COW     0x1000
static int pte_write(pte_t p) { return (p & 1) != 0; }
static int pte_dirty(pte_t p) { return (p & 2) != 0; }

/* ==== exact helper text extracted from the candidate mm/gup.c ==== */
static inline bool can_follow_write_pte(pte_t pte, unsigned int flags)
{
	return pte_write(pte) ||
		((flags & FOLL_FORCE) && (flags & FOLL_COW) && pte_dirty(pte));
}
/* ================================================================ */

/* Candidate guard: follow_page_pte() denies (returns NULL) when FOLL_WRITE
 * is set and can_follow_write_pte() is false. */
static int write_allowed(pte_t pte, unsigned int flags)
{
	if ((flags & FOLL_WRITE) && !can_follow_write_pte(pte, flags))
		return 0; /* deny */
	return 1;     /* allow */
}

int main(void)
{
	/* positive: a genuinely writable pte is always allowed */
	assert(write_allowed(1UL, FOLL_WRITE) == 1);
	/* positive: FOLL_FORCE + FOLL_COW + dirty (real completed COW) allowed */
	assert(write_allowed(2UL, FOLL_WRITE|FOLL_FORCE|FOLL_COW) == 1);
	/* negative (original vulnerability window): unwritable, not dirty -> deny */
	assert(write_allowed(0UL, FOLL_WRITE|FOLL_FORCE|FOLL_COW) == 0);
	/* negative: COW flag absent -> deny even if dirty */
	assert(write_allowed(2UL, FOLL_WRITE|FOLL_FORCE) == 0);
	/* negative: FOLL_FORCE absent -> deny */
	assert(write_allowed(2UL, FOLL_WRITE|FOLL_COW) == 0);
	/* read-only access (no FOLL_WRITE) unaffected -> allow */
	assert(write_allowed(0UL, FOLL_FORCE|FOLL_COW) == 1);
	printf("PASS: can_follow_write_pte truth table (2 positive, 3 negative, 1 passthrough)\n");
	return 0;
}

